import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import com.google.gson.*;
import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.address.*;
import ghidra.program.model.data.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.pcode.*;
import ghidra.program.model.lang.Register;
import ghidra.program.model.symbol.SourceType;

public class ExportTypedBatch extends GhidraScript {
    private static final String PIN="fde7cd6542ab00e3952d0366c0c5c52dde59a70160280f172e24d41406d33c8d";
    private String address(Address a){return a==null?null:a.getAddressSpace().getName()+":"+Long.toUnsignedString(a.getOffset(),16);}
    private JsonElement type(DataType t){if(t==null)return JsonNull.INSTANCE;JsonObject j=new JsonObject();j.addProperty("name",t.getName());j.addProperty("display",t.getDisplayName());j.addProperty("path",t.getPathName());j.addProperty("size_bytes",t.getLength());j.addProperty("java_class",t.getClass().getName());if(t instanceof Pointer p)j.add("pointee",type(p.getDataType()));if(t instanceof Array a){j.addProperty("elements",a.getNumElements());j.add("element",type(a.getDataType()));}return j;}
    private JsonElement high(HighVariable h){if(h==null)return JsonNull.INSTANCE;JsonObject j=new JsonObject();j.addProperty("class",h.getClass().getSimpleName());j.addProperty("name",h.getName());j.addProperty("size_bytes",h.getSize());j.add("datatype",type(h.getDataType()));Varnode r=h.getRepresentative();j.addProperty("representative",r==null?null:address(r.getAddress()));if(h instanceof HighGlobal g)j.add("symbol",symbol(g.getSymbol()));return j;}
    private JsonElement symbol(HighSymbol s){if(s==null)return JsonNull.INSTANCE;JsonObject j=new JsonObject();j.addProperty("id",s.getId());j.addProperty("name",s.getName());j.addProperty("size_bytes",s.getSize());j.add("datatype",type(s.getDataType()));JsonArray storage=new JsonArray();if(s.getStorage()!=null)for(Varnode v:s.getStorage().getVarnodes())storage.add(node(v,false));j.add("storage",storage);return j;}
    private JsonElement node(Varnode v,boolean includeHigh){if(v==null)return JsonNull.INSTANCE;JsonObject j=new JsonObject();j.addProperty("address",address(v.getAddress()));j.addProperty("size_bytes",v.getSize());j.addProperty("constant",v.isConstant());j.addProperty("register",v.isRegister());j.addProperty("memory",v.isAddress());j.addProperty("unique",v.isUnique());if(includeHigh&&v instanceof VarnodeAST a)j.add("high",high(a.getHigh()));return j;}
    private JsonObject op(PcodeOp p){JsonObject j=new JsonObject();j.addProperty("site",address(p.getSeqnum().getTarget()));j.addProperty("sequence",p.getSeqnum().getTime());j.addProperty("opcode",p.getMnemonic());JsonArray in=new JsonArray();for(int i=0;i<p.getNumInputs();i++)in.add(node(p.getInput(i),true));j.add("inputs",in);j.add("output",node(p.getOutput(),true));return j;}
    private String fixed(Address a){return String.format("%08x",a.getOffset());}
    private JsonObject describe(Function f,DecompileResults r,String entry) throws Exception {
        JsonObject j=new JsonObject();j.addProperty("entry",entry);j.addProperty("listing_signature_advisory",f.getPrototypeString(false,true));JsonArray nativeCode=new JsonArray(),returns=new JsonArray(),callsites=new JsonArray();
        InstructionIterator it=currentProgram.getListing().getInstructions(f.getBody(),true);
        while(it.hasNext()){Instruction ins=it.next();JsonObject n=new JsonObject();n.addProperty("address",fixed(ins.getAddress()));n.addProperty("instruction",ins.toString());n.addProperty("bytes",HexFormat.of().formatHex(ins.getBytes()));JsonArray reads=new JsonArray(),writes=new JsonArray(),flows=new JsonArray();for(Object o:ins.getInputObjects())if(o instanceof Register reg)reads.add(reg.getName());for(Object o:ins.getResultObjects())if(o instanceof Register reg)writes.add(reg.getName());for(Address a:ins.getFlows())flows.add(fixed(a));n.add("register_reads",reads);n.add("register_writes",writes);n.add("flow_targets",flows);n.addProperty("fallthrough",ins.getFallThrough()==null?null:fixed(ins.getFallThrough()));n.addProperty("native_call",ins.getFlowType().isCall());n.addProperty("native_jump",ins.getFlowType().isJump());
            JsonArray pc=new JsonArray();for(PcodeOp po:ins.getPcode())pc.add(op(po));n.add("raw_pcode",pc);nativeCode.add(n);
            if(ins.getMnemonicString().startsWith("RET"))returns.add(n.deepCopy());if(ins.getFlowType().isCall())callsites.add(n.deepCopy());
        }j.add("native_instructions",nativeCode);j.add("native_return_sites",returns);j.add("native_callsites",callsites);
        if(r==null||!r.decompileCompleted()||r.getHighFunction()==null||r.getDecompiledFunction()==null){j.addProperty("status","decompile_unavailable");j.addProperty("error",r==null?"No result":r.getErrorMessage());return j;}
        HighFunction hf=r.getHighFunction();j.addProperty("status","facts_complete");j.addProperty("raw_pseudocode",r.getDecompiledFunction().getC());j.addProperty("decompile_error",r.getErrorMessage());FunctionPrototype fp=hf.getFunctionPrototype();JsonObject proto=new JsonObject();proto.addProperty("calling_model_advisory",fp.getModelName());proto.add("return_datatype",type(fp.getReturnType()));proto.addProperty("return_storage_advisory",fp.getReturnStorage().toString());JsonArray params=new JsonArray();for(int i=0;i<fp.getNumParams();i++)params.add(symbol(fp.getParam(i)));proto.add("parameters",params);j.add("logical_prototype",proto);
        JsonArray globals=new JsonArray();Iterator<HighSymbol> gi=hf.getGlobalSymbolMap().getSymbols();while(gi.hasNext()){HighSymbol sym=gi.next();JsonObject g=symbol(sym).getAsJsonObject();Address a=sym.getStorage()==null?null:sym.getStorage().getMinAddress();Data data=a==null?null:currentProgram.getListing().getDataAt(a);g.add("listing_datatype_advisory",data==null?JsonNull.INSTANCE:type(data.getDataType()));globals.add(g);}j.add("global_symbols",globals);
        JsonArray tokens=new JsonArray();List<ClangNode> flat=new ArrayList<>();r.getCCodeMarkup().flatten(flat);int ordinal=0;for(ClangNode cn:flat){if(cn instanceof ClangToken t){JsonObject q=new JsonObject();q.addProperty("ordinal",ordinal++);q.addProperty("text",t.getText());q.addProperty("class",t.getClass().getSimpleName());q.addProperty("min_address",address(t.getMinAddress()));q.addProperty("max_address",address(t.getMaxAddress()));q.add("varnode",node(t.getVarnode(),true));q.add("high_variable",high(t.getHighVariable()));PcodeOp po=t.getPcodeOp();q.add("pcode",po==null?JsonNull.INSTANCE:op(po));tokens.add(q);}}j.add("clang_tokens",tokens);
        JsonArray operations=new JsonArray();Iterator<PcodeOpAST> pi=hf.getPcodeOps();while(pi.hasNext())operations.add(op(pi.next()));j.add("high_pcode",operations);return j;
    }
    private JsonObject conflictFacts(JsonObject seed) throws Exception {
        JsonObject j=new JsonObject();j.addProperty("entry",seed.get("entry").getAsString());j.addProperty("status","qualified_boundary_conflict_native_facts_only");j.add("boundary_conflict",seed.get("boundary_conflict"));JsonArray nativeCode=new JsonArray();
        for(JsonElement e:seed.getAsJsonArray("expected_instructions")){JsonArray q=e.getAsJsonArray();Address pc=toAddr(q.get(0).getAsString());if(getInstructionAt(pc)==null)disassemble(pc);Instruction ins=getInstructionAt(pc);JsonObject n=new JsonObject();n.addProperty("address",fixed(pc));n.addProperty("bytes",HexFormat.of().formatHex(ins.getBytes()));n.addProperty("instruction",ins.toString());JsonArray reads=new JsonArray(),writes=new JsonArray();for(Object o:ins.getInputObjects())if(o instanceof Register r)reads.add(r.getName());for(Object o:ins.getResultObjects())if(o instanceof Register r)writes.add(r.getName());n.add("register_reads",reads);n.add("register_writes",writes);JsonArray ops=new JsonArray();for(PcodeOp op:ins.getPcode())ops.add(op(op));n.add("raw_pcode",ops);nativeCode.add(n);}j.add("native_instructions",nativeCode);j.addProperty("HighFunction_unavailable_reason","Disputed cached function boundary: no independent function or ABI materialized in this private project");return j;
    }
    public void run() throws Exception {
        String[] args=getScriptArgs();if(args.length!=2)throw new IllegalArgumentException("Seed and private output required");Path seedPath=Path.of(args[0]).toAbsolutePath().normalize(),out=Path.of(args[1]).toAbsolutePath().normalize();String expected="\\restore\\build\\bulk-type-batch\\";
        String projectRaw=state.getProject().getProjectLocator().getLocation();if(projectRaw.matches("^/[A-Za-z]:/.*"))projectRaw=projectRaw.substring(1);Path project=Path.of(projectRaw).toAbsolutePath().normalize();for(Path p:new Path[]{seedPath,out,project})if(!p.toString().toLowerCase().contains(expected))throw new IllegalArgumentException("Nonprivate target");if(!PIN.equalsIgnoreCase(currentProgram.getExecutableSHA256()))throw new IllegalArgumentException("Wrong imported SHA256");
        JsonObject seed=JsonParser.parseString(Files.readString(seedPath)).getAsJsonObject();if(!PIN.equals(seed.get("native_sha256").getAsString())||!seed.get("known_cache_only").getAsBoolean())throw new IllegalArgumentException("Bad seed authority");JsonArray entries=seed.getAsJsonArray("functions");Files.createDirectories(out);Gson gson=new GsonBuilder().disableHtmlEscaping().create();JsonArray seeding=new JsonArray();int count=0;
        for(JsonElement e:entries){JsonObject s=e.getAsJsonObject();String entry=s.get("entry").getAsString();JsonObject row=new JsonObject();row.addProperty("entry",entry);try{if(s.has("boundary_conflict")&&!s.get("boundary_conflict").isJsonNull())throw new IllegalStateException("Qualified disputed boundary; no function created");Address at=toAddr(entry);AddressSet body=new AddressSet();for(JsonElement range:s.getAsJsonArray("body_ranges")){JsonArray p=range.getAsJsonArray();body.addRange(toAddr(p.get(0).getAsString()),toAddr(p.get(1).getAsString()));}for(JsonElement v:s.getAsJsonArray("expected_instructions")){JsonArray p=v.getAsJsonArray();Address pc=toAddr(p.get(0).getAsString());byte[] bytes=HexFormat.of().parseHex(p.get(1).getAsString());byte[] actual=new byte[bytes.length];currentProgram.getMemory().getBytes(pc,actual);if(!Arrays.equals(bytes,actual))throw new IllegalArgumentException("Pinned byte mismatch");if(getInstructionAt(pc)==null)disassemble(pc);}
                Function f=getFunctionAt(at);if(f==null)f=currentProgram.getFunctionManager().createFunction(null,at,body,SourceType.ANALYSIS);else f.setBody(body);if(f==null)throw new IllegalStateException("No private function");row.addProperty("status","seeded_known_function");
            }catch(Exception error){row.addProperty("status","seed_failed");row.addProperty("error",error.toString());}seeding.add(row);++count;if(count%200==0){Files.writeString(out.resolve("seeding-progress.json"),gson.toJson(seeding));println("BATCH_SEED "+count+"/"+entries.size());}}
        Files.writeString(out.resolve("seeding.json"),gson.toJson(seeding));DecompInterface dec=new DecompInterface();dec.toggleCCode(true);dec.toggleSyntaxTree(true);if(!dec.openProgram(currentProgram))throw new IllegalStateException("Cannot open private program");JsonArray index=new JsonArray();count=0;
        try{for(JsonElement e:entries){JsonObject s=e.getAsJsonObject();String entry=s.get("entry").getAsString();JsonObject wrapper=new JsonObject();wrapper.addProperty("native_sha256",PIN);wrapper.addProperty("ghidra_version",ghidra.framework.Application.getApplicationVersion());wrapper.addProperty("language",currentProgram.getLanguageID().toString());wrapper.addProperty("private_project",project.toString());wrapper.add("seed",s);Function f=getFunctionAt(toAddr(entry));JsonObject body;
                if(s.has("boundary_conflict")&&!s.get("boundary_conflict").isJsonNull()){body=conflictFacts(s);}else if(f==null){body=new JsonObject();body.addProperty("entry",entry);body.addProperty("status","seed_unavailable");}else{DecompileResults r=null;try{r=dec.decompileFunction(f,30,monitor);body=describe(f,r,entry);}catch(Exception error){body=describe(f,null,entry);body.addProperty("exception",error.toString());}}wrapper.add("function",body);Files.writeString(out.resolve(entry+".json"),gson.toJson(wrapper));JsonObject summary=new JsonObject();summary.addProperty("entry",entry);summary.addProperty("status",body.get("status").getAsString());summary.addProperty("native_instructions",body.has("native_instructions")?body.getAsJsonArray("native_instructions").size():0);summary.addProperty("protected",s.get("protected_function").getAsBoolean());index.add(summary);++count;
                if(count%25==0){Files.writeString(out.resolve("progress.json"),gson.toJson(index));println("BATCH_FACTS "+count+"/"+entries.size());dec.flushCache();}
            }}finally{dec.dispose();}Files.writeString(out.resolve("index.json"),gson.toJson(index));println("TYPED_BATCH_COMPLETE "+count);
    }
}
